/**
 * HorPlus LOCAL-07 — Session Implementation Compatibility Proof
 * 
 * Verifies that the encrypted session cookies and CSRF tokens generated by
 * login-helper.mjs are 100% compatible with the actual HorPlus API auth middleware.
 * 
 * Tests all 6 personas against real endpoints:
 * 1. registration-owner: GET /api/v1/auth/session -> 200, onboardingRequired = true, memberships = []
 * 2. fresh-owner:        GET /api/v1/auth/session -> 200, role = OWNER, 1 membership
 * 3. comp-owner:         GET /api/v1/auth/session -> 200, role = OWNER, 1 membership
 * 4. manager:            GET /api/v1/auth/session -> 200, role = MANAGER
 * 5. tech:               GET /api/v1/auth/session -> 200, role = TECH
 * 6. tenant-somchai:     GET /api/v1/tenant-portal/contract/pdf -> 200, returns contract PDF
 * 
 * @license Apache-2.0
 */

import { createRequire } from 'module';
const require = createRequire(import.meta.url);
const request = require('../../server/node_modules/supertest/index.js');

import { assertSafeDatabaseTarget } from './db-safety-guard.mjs';
import { REGISTRATION_OWNER, FRESH_DORM, COMP_DORM } from './constants.mjs';
import { createApp } from '../../server/src/app.js';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT_DIR = path.resolve(__dirname, '../..');
const SESSIONS_DIR = path.join(ROOT_DIR, '.local07-sessions');

const targetInfo = assertSafeDatabaseTarget();

export async function runSessionCompatibilityProof() {
  console.log('================================================================================');
  console.log('  HORPLUS LOCAL-07 — SESSION IMPLEMENTATION COMPATIBILITY PROOF');
  console.log('================================================================================');
  console.log(`Target: ${targetInfo.host}:${targetInfo.port}/${targetInfo.database}\n`);

  const manifestPath = path.join(SESSIONS_DIR, 'manifest.json');
  if (!fs.existsSync(manifestPath)) {
    throw new Error('Manifest file not found at .local07-sessions/manifest.json. Run `npm run uat:refresh` or `npm run uat:login` first.');
  }

  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const app = createApp({ forcePrisma: true });

  let passed = 0;
  let failed = 0;

  function assert(condition, testName, details = '') {
    if (condition) {
      console.log(`  ✅ PASS: ${testName}`);
      passed++;
    } else {
      console.error(`  ❌ FAIL: ${testName} — ${details}`);
      failures++;
    }
  }

  // 1. Registration Owner
  console.log('--- 1. Testing Registration Owner Persona Session ---');
  const regSession = manifest['registration-owner'];
  assert(Boolean(regSession), 'Registration Owner manifest entry exists');
  const regRes = await request(app)
    .get('/api/v1/auth/session')
    .set('Cookie', `horplus_session=${regSession.sessionToken}; horplus_csrf=${regSession.csrfToken}`);
  assert(regRes.status === 200, 'Registration Owner GET /session returns HTTP 200', `Status: ${regRes.status}`);
  assert(regRes.body?.data?.authenticated === true, 'Registration Owner authenticated is true');
  assert(regRes.body?.data?.user?.id === REGISTRATION_OWNER.id, 'Registration Owner user ID matches exactly');
  assert(regRes.body?.data?.onboardingRequired === true, 'Registration Owner onboardingRequired is true');
  assert(regRes.body?.data?.memberships?.length === 0, 'Registration Owner active memberships is 0');

  // 2. Fresh Owner
  console.log('\n--- 2. Testing Fresh Owner Persona Session ---');
  const freshSession = manifest['fresh-owner'];
  assert(Boolean(freshSession), 'Fresh Owner manifest entry exists');
  const freshRes = await request(app)
    .get('/api/v1/auth/session')
    .set('Cookie', `horplus_session=${freshSession.sessionToken}; horplus_csrf=${freshSession.csrfToken}`);
  assert(freshRes.status === 200, 'Fresh Owner GET /session returns HTTP 200', `Status: ${freshRes.status}`);
  assert(freshRes.body?.data?.authenticated === true, 'Fresh Owner authenticated is true');
  assert(freshRes.body?.data?.user?.id === FRESH_DORM.owner.id, 'Fresh Owner user ID matches');
  assert(freshRes.body?.data?.onboardingRequired === false, 'Fresh Owner onboardingRequired is false');
  assert(freshRes.body?.data?.memberships?.length > 0, 'Fresh Owner has active membership');
  assert(freshRes.body?.data?.memberships?.[0]?.roleCode === 'OWNER', 'Fresh Owner role is OWNER');

  // 3. Comprehensive Owner
  console.log('\n--- 3. Testing Comprehensive Owner Persona Session ---');
  const compSession = manifest['comp-owner'];
  assert(Boolean(compSession), 'Comp Owner manifest entry exists');
  const compRes = await request(app)
    .get('/api/v1/auth/session')
    .set('Cookie', `horplus_session=${compSession.sessionToken}; horplus_csrf=${compSession.csrfToken}`);
  assert(compRes.status === 200, 'Comp Owner GET /session returns HTTP 200', `Status: ${compRes.status}`);
  assert(compRes.body?.data?.user?.id === COMP_DORM.owner.id, 'Comp Owner user ID matches');
  assert(compRes.body?.data?.memberships?.[0]?.roleCode === 'OWNER', 'Comp Owner role is OWNER');

  // 4. Staff Manager
  console.log('\n--- 4. Testing Staff Manager Persona Session ---');
  const mgrSession = manifest['manager'];
  assert(Boolean(mgrSession), 'Manager manifest entry exists');
  const mgrRes = await request(app)
    .get('/api/v1/auth/session')
    .set('Cookie', `horplus_session=${mgrSession.sessionToken}; horplus_csrf=${mgrSession.csrfToken}`);
  assert(mgrRes.status === 200, 'Manager GET /session returns HTTP 200', `Status: ${mgrRes.status}`);
  assert(mgrRes.body?.data?.user?.id === COMP_DORM.manager.id, 'Manager user ID matches');
  assert(mgrRes.body?.data?.memberships?.[0]?.roleCode === 'MANAGER', 'Manager role is MANAGER');

  // 5. Staff Tech
  console.log('\n--- 5. Testing Staff Tech Persona Session ---');
  const techSession = manifest['tech'];
  assert(Boolean(techSession), 'Tech manifest entry exists');
  const techRes = await request(app)
    .get('/api/v1/auth/session')
    .set('Cookie', `horplus_session=${techSession.sessionToken}; horplus_csrf=${techSession.csrfToken}`);
  assert(techRes.status === 200, 'Tech GET /session returns HTTP 200', `Status: ${techRes.status}`);
  assert(techRes.body?.data?.user?.id === COMP_DORM.tech.id, 'Tech user ID matches');
  assert(techRes.body?.data?.memberships?.[0]?.roleCode === 'TECH', 'Tech role is TECH');

  // 6. Tenant Somchai (Authoritative Tenant Endpoint)
  console.log('\n--- 6. Testing Tenant Somchai Persona Session ---');
  const tenantSession = manifest['tenant-somchai'];
  assert(Boolean(tenantSession), 'Tenant manifest entry exists');
  const tenantRes = await request(app)
    .get('/api/v1/tenant-portal/contract/pdf')
    .set('Cookie', `horplus_session=${tenantSession.sessionToken}; horplus_csrf=${tenantSession.csrfToken}`);
  assert(tenantRes.status === 200, 'Tenant GET /tenant-portal/contract/pdf returns HTTP 200 PDF stream', `Status: ${tenantRes.status}`);

  console.log('\n================================================================================');
  console.log(`Summary: ${passed} passed, ${failed} failed`);
  console.log('================================================================================\n');

  if (failed > 0) {
    process.exit(1);
  }
}

if (process.argv[1] === new URL(import.meta.url).pathname || process.argv[1]?.endsWith('test-session-compat.mjs')) {
  runSessionCompatibilityProof()
    .then(() => process.exit(0))
    .catch((err) => {
      console.error(`❌ [SESSION COMPATIBILITY ERROR] ${err.message}`);
      process.exit(1);
    });
}
